(async () => {
	let userInput = "";

	await new Promise((resolve) => {
		new Dialog({
			title: "Find Document by UUID or ID",
			content: `
				<form>
					<p>Enter a UUID (e.g. <code>Actor.WqdJ4AGDhdEADNSO</code>) or just an ID (e.g. <code>WqdJ4AGDhdEADNSO</code>):</p>
					<input type="text" name="docid" style="width:100%;" autofocus />
				</form>
			`,
			buttons: {
				ok: {
					label: "Search",
					callback: (html) => {
						const input = html[0].querySelector("input[name='docid']");
						userInput = input?.value?.trim() ?? "";
						resolve();
					}
				},
				cancel: {
					label: "Cancel",
					callback: () => {
						console.warn("🔍 Document search cancelled.");
						resolve();
					}
				}
			},
			default: "ok"
		}).render(true);
	});

	if (!userInput) {
		console.warn("❌ No ID or UUID entered. Search aborted.");
		return;
	}

	const results = [];

	if (userInput.includes(".")) {
		// Treat as UUID
		try {
			const doc = await fromUuid(userInput);
			if (doc) {
				results.push({
					name: doc.name,
					type: doc.documentName,
					uuid: doc.uuid,
					sheet: doc.sheet
				});
			}
		} catch (e) {
			console.error(`Error trying to fetch UUID: ${userInput}`, e);
		}
	} else {
		// Treat as raw ID, search all world-level documents
		const collections = [
			game.actors,
			game.items,
			game.journal,
			game.scenes,
			game.macros,
			game.tables,
			game.playlists
		];

		for (const collection of collections) {
			const doc = collection.get(userInput);
			if (doc) {
				results.push({
					name: doc.name,
					type: collection.documentName,
					uuid: doc.uuid,
					sheet: doc.sheet
				});
			}
		}
	}

	if (results.length === 0) {
		ui.notifications.warn(`No document found matching "${userInput}".`);
		console.info(`🔍 Search complete. No document found matching: ${userInput}`);
		return;
	}

	const list = results.map(r => `
		<li>
			<strong>${r.name}</strong> (${r.type})<br>
			<code>${r.uuid}</code>
		</li>
	`).join("");

	new Dialog({
		title: "Document Search Results",
		content: `<div style="max-height: 400px; overflow-y: auto;"><ul>${list}</ul></div>`,
		buttons: {
			open: {
				label: "Open First",
				callback: () => results[0].sheet?.render?.(true)
			},
			close: { label: "Close" }
		}
	}).render(true);

	console.info(`✅ Found ${results.length} document(s) for "${userInput}":`, results);
})();
